import tempfile
from unittest.mock import patch
from trading_researcher.coordination import Broker,Denied
with tempfile.TemporaryDirectory() as directory:
 broker=Broker(directory)
 try:
  worker=broker.call(broker.admin_token,'register_worker',name='binding-discovery-negative',role='discovery',capabilities=[])['token']
  with patch.object(broker,'_artifact',side_effect=AssertionError('Unauthorized artifact read')):
   for op,args in [('compile_hypothesis',{}),('execute_development',{'compiled_id':'not-readable'})]:
    try:broker.call(worker,op,**args)
    except Denied:print(op+': discovery DENIED before artifact read')
    else:raise AssertionError('Unauthorized operation accepted')
 finally:broker.close()
